// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x1234);
        // Alice deposits 1 wei
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.deposit{value: 1}();
        // Alice is a contract without receive/fallback so sending ether reverts
        // But the contract will try to send ether to alice via call; on correct C, withdrawAll reverts
        // On buggy M, withdrawAll does not revert
        // We wrap in try/catch to see if revert happens
        bool didRevert = false;
        vm.prank(alice);
        try c.withdrawAll() {
            // no revert => buggy version
            didRevert = false;
        } catch {
            didRevert = true;
        }
        // If correct: withdrawAll reverts => alice still has credit 1, balance is 1
        // If buggy: withdrawAll does not revert => alice credit 0, balance 0
        // So we check address(c).balance — in correct it's 1, in buggy it's 0
        assertTrue(address(c).balance == 1, "Expected reference behavior: balance remains 1");
    }
}

