pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Scenario: user A deposits 1 wei (creates nonzero credit for A)
        address alice = address(0x1234);
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.deposit{value: 1}();

        // Now user B (with zero credit) calls withdrawAll
        // Reference: oCredit = 0, condition (0 > 0) false => no transfer, balance unchanged (= 1 wei)
        // Bug: oCredit = 0, condition (0 >= 0) true => sends 0 wei, balance decreases by 0 => balance = 0
        address bob = address(0x5678);
        vm.prank(bob);
        c.withdrawAll();

        // Assert: after Bob's withdrawAll, contract's own balance should still be 1 wei (reference behavior)
        // This assertion fails on bug version because balance becomes 0.
        assertTrue(address(c).balance == 1, "Balance should be 1 wei after no-op withdrawAll");
    }
}

